pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;

    function setUp() public { lg = new Log(); c = new C(address(lg)); }

    function testFuzz_property(address actor, uint96 amount, uint unlockTime) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(amount > 0);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // General rule: every deposit via Put is logged in the Log contract's History.
        // Reading the first history entry must succeed and reflect the deposit.
        bool logged = true;
        address sender;
        uint val;
        try lg.History(0) returns (address s, string memory, uint v, uint) {
            sender = s;
            val = v;
        } catch {
            logged = false;
        }
        assertTrue(logged && sender == actor && val == amount);
    }
}

