pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }
    function testFuzz_property(uint256 amount, uint256 warpTo) public {
        // admissible domain: a real withdrawal of at least MinSum (1 ether), any future timestamp
        amount = bound(amount, 1 ether, 1000 ether);
        warpTo = bound(warpTo, 2, 2 ** 60);
        Att att = new Att(c);
        // fund and prime the attacker: a first Put (allowed at top level), then time passes
        vm.deal(address(att), 2 * amount);
        vm.prank(address(att));
        c.Put{value: 2 * amount}(0);
        vm.warp(warpTo);
        // attacker withdraws; during the payout callback it RE-ENTERS Put (re-entry must be blocked)
        att.go(amount);
        // General rule: a nested Put can never succeed, so after Collect settles the
        // attacker's recorded balance must have decreased by exactly the withdrawal amount
        // (from 2*amount down to amount) and nothing extra may have been credited during re-entry.
        assertTrue(c.Acc(address(att)) == amount);
    }
}

contract Att {
    C c;
    uint256 reAmt;
    constructor(C _c) { c = _c; }
    function go(uint256 amt) external {
        reAmt = amt;
        c.Collect(amt);
    }
    receive() external payable {
        // re-entrant Put while C is mid-payout: P reverts (locked), M succeeds
        c.Put{value: reAmt}(0);
    }
}

