pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 unlockTime, uint256 nestedVal) public {
        // Keep params in the admissible domain (wide)
        amount = bound(amount, 1 ether, 100 ether);        // must satisfy acc.balance >= MinSum (1 ether)
        unlockTime = bound(unlockTime, 0, 1_000_000);      // any unlock time; we warp past it
        nestedVal = bound(nestedVal, 1, 1 ether);          // nested Put must carry a nonzero value

        vm.warp(2_000_000);                                // block.timestamp > any bounded unlockTime

        // Adversarial counterparty: re-entrant payee whose receive() nests a Put during Collect's payout
        Attacker att = new Attacker(c, nestedVal);

        // Payee funds itself via a normal Put
        vm.deal(address(att), amount);
        vm.prank(address(att));
        c.Put{value: amount}(unlockTime);

        // Fresh ether for the nested Put attempt during the payout
        vm.deal(address(att), nestedVal);

        // Drive Collect from the payee; during the ETH transfer its receive() tries a nested Put
        att.attack(amount);

        // Rule: while C holds the lock during a payout, any nested Put must revert.
        // Reference C: nestedReverted == true for every input. Mutant: nested Put succeeds -> false.
        assertTrue(att.nestedReverted());
    }
}

contract Attacker {
    C immutable c;
    uint256 immutable v;
    bool public nestedReverted;

    constructor(C _c, uint256 _v) {
        c = _c;
        v = _v;
    }

    function attack(uint256 am) external {
        c.Collect(am);
    }

    receive() external payable {
        try c.Put{value: v}(0) {
            nestedReverted = false;
        } catch {
            nestedReverted = true;
        }
    }
}

