pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;
    uint256 constant F = 2 ether;

    function setUp() public { c = new C(address(new Log())); attacker = new Attacker(c); }

    function testFuzz_property(uint256 am, uint256 nv) public {
        am = bound(am, 2, F);
        nv = bound(nv, 1, am - 1);

        vm.deal(address(this), F);
        attacker.fund{value: F}();          // attacker balance in c = F, unlockTime = now
        vm.warp(block.timestamp + 1);       // unlockTime now in the past

        attacker.attack(am, nv);            // Collect(am); nested Put(nv) from receive()

        // Rule: because the guard blocks the nested Put, the Collect fails as a whole
        // (attacker's receive reverts, low-level call returns false) and the recorded
        // balance is untouched. In the mutant the nested Put succeeds, so the recorded
        // balance becomes F + nv - am != F.
        (, uint256 bal) = c.Acc(address(attacker));
        assertTrue(bal == F, "failed Collect must leave recorded balance unchanged");
    }
}

contract Attacker {
    C c;
    uint256 nestedVal;

    constructor(C _c) { c = _c; }

    function fund() external payable { c.Put{value: msg.value}(0); }

    function attack(uint256 am, uint256 nv) external {
        nestedVal = nv;
        c.Collect(am);
    }

    receive() external payable {
        c.Put{value: nestedVal}(0); // reverts under the lock in the reference
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint amountPut, uint am) external {
        require(amountPut >= 1 ether);
        require(am > 0 && am <= amountPut);
        require(address(this).balance >= amountPut);

        c.Put{value: amountPut}(block.timestamp);

        uint before = address(this).balance;
        c.Collect{value: 0}(am);

        bool paid = address(this).balance == before + am;
        assert(!paid || c.Acc(address(this)).balance == amountPut - am);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amountPut, uint _am) public payable {
        require(address(this).balance >= amountPut, "insufficient funds");
        c.Put{value: amountPut}(0);
        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }
        (, uint bal) = c.Acc(address(this));
        assert(reverted || bal == amountPut - _am);
    }
    receive() external payable {}
}

